from lib import *
S = SS('n46')
steps = [
    step("用标准库 http.TimeoutHandler(r, 100ms, \"超时了\") 包住 Gin:客户端在 103 ms 收到 503 和 \"超时了\";但 handler 并没有被打断——303 ms 才睡醒,此时 Request.Context().Err() 是 context deadline exceeded(超时时被取消了),它再写响应,c.Writer.WriteString 得到 err=http: Handler timeout,内容被丢弃。也就是说客户端早就走了,服务端的工作做完了才发现没人收。", t=tl(S(1)), mark=lidx(S(1), '客户端收到 503', 'http: Handler timeout', 'context deadline exceeded'), done=lidx(S(1), 'handler 开始'), b=bars([['客户端拿到 503', 103, '103 ms'], ['handler 实际结束', 303, '303 ms']], 303, done=[0], mark=[1]), kv=KV([['客户端', '100 ms 得到 503'], ['handler', '继续跑到 300 ms,写出被丢弃'], ['Request.Context()', '超时时已经被取消']], ['handler'])),
    step("用 context 超时并让 handler 配合:中间件给 Request 换成 100 ms 超时的 context,handler 里 select 同时等 time.After 和 Request.Context().Done()——103 ms 收到取消,立即返回 504,104 ms 客户端收到 504 与 JSON,handler 也在 104 ms 结束,没有浪费 200 ms。", t=tl(S(2)), mark=lidx(S(2), 'handler 收到取消', '客户端收到 504'), done=lidx(S(2), 'handler 开始', 'handler 返回'), kv=KV([['配合 context', 'handler 立刻停下,不浪费资源'], ['客户端', '104 ms 得到 504'], ['前提', 'handler 里的阻塞操作要接受 context']], ['前提'])),
    step("如果 handler 里调用的是不接受 context 的慢函数(这里是 time.Sleep),context 超时对它没有任何作用:300 ms 后返回 200,正文里才看到 ctx.Err()=context deadline exceeded——context 只是一个信号,必须有人去检查它。", t=tl(S(3)), mark=lidx(S(3), '200', 'deadline exceeded'), kv=KV([['context', '只是取消信号,不会打断代码'], ['不检查的 handler', '照常跑完,客户端等满 303 ms']], ['context'])),
    step("http.Server 的 WriteTimeout=100 ms 与 TimeoutHandler 的区别:handler 300 ms 的情况下,WriteTimeout 不会提前回应,而是在响应写出时发现超过了写截止时间,客户端等了 301 ms,最后什么都没收到(错误 EOF,状态 0);TimeoutHandler 则在 102 ms 返回 503 与指定正文。WriteTimeout 对客户端是“等了很久然后断连接”。", t=tl(S(4)), mark=lidx(S(4), 'WriteTimeout=100ms'), done=lidx(S(4), 'TimeoutHandler=100ms'), b=bars([['WriteTimeout:客户端等待', 301, '301 ms 后 EOF'], ['TimeoutHandler:客户端等待', 102, '102 ms 得到 503']], 301, mark=[0], done=[1]), kv=KV([['WriteTimeout', '到点不回应,写出时才断开,客户端 EOF'], ['TimeoutHandler', '到点返回 503 与正文'], ['共同点', '都不会打断 handler']], ['WriteTimeout'])),
    step("r.Run / RunListener 创建的 http.Server 只有 Handler 一个字段(源码里 `server := &http.Server{Handler: engine.Handler()}`,带 #nosec G112 注释),没有任何超时:一个只发了一半请求头的连接,等了 1501 ms 服务端仍没有关闭(慢速攻击会一直占着连接);自己创建 http.Server 并设 ReadHeaderTimeout=300 ms,则 300 ms 后连接被关闭(读到 0 字节、EOF)。", t=tl(S(5)), mark=lidx(S(5), 'r.RunListener(默认)', 'server := &http.Server{ // #nosec G112'), done=lidx(S(5), 'ReadHeaderTimeout: 300ms'), b=bars([['r.RunListener(默认)', 1501, '1501 ms 仍未关闭'], ['ReadHeaderTimeout=300ms', 300, '300 ms 后关闭']], 1501, mark=[0], done=[1]), kv=KV([['r.Run', '没有任何超时'], ['慢速请求头', '连接一直被占着'], ['生产环境', '自己创建 http.Server 并设置各项超时']], ['r.Run'])),
]
A = mkartn('n46', 46, 'Gin,超时控制,TimeoutHandler,context,ReadHeaderTimeout,Go,真实验证,动画演示',
    '在 Gin v1.12.0 里实测超时控制:http.TimeoutHandler 100 ms 后客户端得到 503,但 handler 继续跑到 303 ms;用 context 超时并让 handler 配合则 104 ms 就能结束;不检查 context 的 handler 照常跑完;WriteTimeout 让客户端等 301 ms 后 EOF;r.Run 创建的 http.Server 没有任何超时,发一半请求头的连接 1.5 秒仍不被关闭。',
    '请求超时有三种常见做法:TimeoutHandler、context 超时、http.Server 的各种 Timeout。它们对客户端和 handler 的效果完全不同。这篇用一个 300 ms 的慢 handler 和 100 ms 的超时,把三种方式的响应、handler 是否被打断、以及 r.Run 默认没有任何超时这件事一一实测。',
    [('103 ms vs 303 ms', 'TimeoutHandler 下客户端收到 503 的时间 vs handler 实际结束的时间'), ('EOF', 'WriteTimeout 到点后客户端拿到的结果:没有响应,连接断开'), ('1501 ms', 'r.RunListener 默认下,发了一半请求头的连接等了这么久也没被关闭')],
    [('TimeoutHandler:只管客户端', '<p><code>http.TimeoutHandler</code> 到点向客户端回 503,但 handler 在另一个 goroutine 里继续跑完:数据库查询照常执行、副作用照常发生,最后写出的内容被丢弃(返回 <code>http.ErrHandlerTimeout</code>)。它给的是客户端体验上的超时,不是资源上的超时。</p>'),
     ('context:要配合', '<p>给 <code>Request</code> 换上带超时的 context,handler 里所有可能阻塞的调用(数据库、HTTP 客户端、<code>select</code>)都接受它,超时才能真正中止工作。不接受 context 的调用不受任何影响。这种方式能返回你自己定义的 504 响应。</p>'),
     ('不检查 context 的 handler', '<p>context 只是一个取消信号,不会打断正在执行的代码。handler 里如果调用的是不接受 context 的慢函数(这里用 <code>time.Sleep</code> 代替),超时对它毫无作用,客户端仍要等满 300 ms。很多“设置了超时却没生效”的问题都是因为中间某一层没有把 context 传下去。</p>'),
     ('WriteTimeout 的体验', '<p><code>WriteTimeout</code> 是连接级的写截止时间,到点时不会返回任何响应,而是在写出时失败、关闭连接:客户端要等到 handler 结束才看到 EOF。它适合作为兜底,不适合当“请求超时”用。</p>'),
     ('r.Run 没有任何超时', '<p><code>r.Run</code> / <code>RunListener</code> 内部的 <code>http.Server</code> 只设了 <code>Handler</code>(源码里连 <code>#nosec G112</code> 的静态检查提示都标了)。慢速发送请求头的连接会被一直保持。生产环境应该自己创建 <code>http.Server</code>,至少设置 <code>ReadHeaderTimeout</code>,再按需要设置 <code>ReadTimeout</code>、<code>WriteTimeout</code>、<code>IdleTimeout</code>,然后 <code>srv.ListenAndServe()</code>。</p>')],
    steps,
    [ENV_N_GIN + '。服务端是真实的 httptest.NewServer(WriteTimeout 与 ReadHeaderTimeout 的实验给 Config 设置对应字段);慢速请求头实验用原始 TCP 连接只发半个请求头;耗时是 time.Now 差,每种情形各一次(数字有几毫秒抖动)',
     '没有验证:TimeoutHandler 与 Gin 中间件(如 Logger、Recovery)组合时日志的内容;被超时的请求在 handler 里 panic 的行为;ReadTimeout、IdleTimeout 的行为(只实验了 WriteTimeout 与 ReadHeaderTimeout);HTTP/2 下的超时;gin-contrib/timeout 等第三方库'],
    '超时控制')
